CREATE TRIGGER leader_submission_checkin BEFORE INSERT ON submission_versions WHEN NOT EXISTS(SELECT 1 FROM teams lt JOIN users lu ON lu.id=lt.leader_id JOIN memberships lm ON lm.user_id=lu.id AND lm.team_id=lt.id JOIN registrations lr ON lr.email=lu.email AND lr.status='approved' WHERE lt.id=NEW.team_id AND COALESCE((SELECT status FROM participant_status_overrides WHERE user_id=lu.id),'Checked in')='Checked in' AND (EXISTS(SELECT 1 FROM check_ins c WHERE c.user_id=lu.id) OR EXISTS(SELECT 1 FROM manual_checkins mc WHERE mc.user_id=lu.id AND mc.verified_email=lower(lu.email)))) BEGIN SELECT RAISE(ABORT,'LEADER_CHECKIN_REQUIRED'); END;

CREATE TRIGGER leader_draft_checkin_insert BEFORE INSERT ON projects WHEN NOT EXISTS(SELECT 1 FROM teams lt JOIN users lu ON lu.id=lt.leader_id JOIN memberships lm ON lm.user_id=lu.id AND lm.team_id=lt.id JOIN registrations lr ON lr.email=lu.email AND lr.status='approved' WHERE lt.id=NEW.team_id AND COALESCE((SELECT status FROM participant_status_overrides WHERE user_id=lu.id),'Checked in')='Checked in' AND (EXISTS(SELECT 1 FROM check_ins c WHERE c.user_id=lu.id) OR EXISTS(SELECT 1 FROM manual_checkins mc WHERE mc.user_id=lu.id AND mc.verified_email=lower(lu.email)))) BEGIN SELECT RAISE(ABORT,'LEADER_CHECKIN_REQUIRED'); END;

CREATE TRIGGER leader_draft_checkin_update BEFORE UPDATE OF draft ON projects WHEN NOT EXISTS(SELECT 1 FROM teams lt JOIN users lu ON lu.id=lt.leader_id JOIN memberships lm ON lm.user_id=lu.id AND lm.team_id=lt.id JOIN registrations lr ON lr.email=lu.email AND lr.status='approved' WHERE lt.id=NEW.team_id AND COALESCE((SELECT status FROM participant_status_overrides WHERE user_id=lu.id),'Checked in')='Checked in' AND (EXISTS(SELECT 1 FROM check_ins c WHERE c.user_id=lu.id) OR EXISTS(SELECT 1 FROM manual_checkins mc WHERE mc.user_id=lu.id AND mc.verified_email=lower(lu.email)))) BEGIN SELECT RAISE(ABORT,'LEADER_CHECKIN_REQUIRED'); END;

CREATE TRIGGER own_project_vote_checkin BEFORE INSERT ON project_upvotes WHEN EXISTS(SELECT 1 FROM projects p JOIN memberships m ON m.team_id=p.team_id WHERE p.id=NEW.project_id AND m.user_id=NEW.user_id) AND NOT EXISTS(SELECT 1 FROM users u JOIN registrations r ON r.email=u.email AND r.status='approved' WHERE u.id=NEW.user_id AND COALESCE((SELECT status FROM participant_status_overrides WHERE user_id=u.id),'Checked in')='Checked in' AND (EXISTS(SELECT 1 FROM check_ins c WHERE c.user_id=u.id) OR EXISTS(SELECT 1 FROM manual_checkins mc WHERE mc.user_id=u.id AND mc.verified_email=lower(u.email)))) BEGIN SELECT RAISE(ABORT,'OWN_PROJECT_CHECKIN_REQUIRED'); END;
